import uuid

from django.conf import settings
from django.db import models
from django.utils.translation import gettext_lazy as _


class UUIDPrimaryKeyModelMixin(models.Model):
    """Provide a UUID primary key for reusable scaffold models.

    Teams can keep this mixin as-is for services that prefer opaque identifiers,
    or replace it with an integer-based primary key strategy if their project has
    different database or reporting requirements.
    """

    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)

    class Meta:
        abstract = True


class DateHistoryModelMixin(models.Model):
    """Track creation and update timestamps automatically.

    This is intended as a default audit baseline for scaffold models. Override or
    extend it when a project needs additional temporal fields such as soft-delete
    timestamps, published dates, or domain-specific event times.
    """

    created_datetime = models.DateTimeField(
        verbose_name=_("Created datetime"),
        auto_now_add=True,
        help_text=_("datetime of object creation"),
    )
    updated_datetime = models.DateTimeField(
        verbose_name=_("Updated datetime"),
        auto_now=True,
        help_text=_("datetime of object update"),
    )

    class Meta:
        abstract = True


class UserHistoryModelMixin(models.Model):
    """Store the users responsible for creating and updating a record.

    The scaffold leaves population of these fields to application code, signals,
    or service-layer helpers. Projects that do not need creator/updater tracking
    can drop this mixin from individual models without affecting the others.
    """

    created_by = models.ForeignKey(
        verbose_name=_("Created by"),
        on_delete=models.SET_NULL,
        related_name="%(app_label)s_%(class)s_created_by",
        to=settings.AUTH_USER_MODEL,
        blank=True,
        null=True,
        help_text=_("User who created the object"),
    )
    updated_by = models.ForeignKey(
        verbose_name=_("Updated by"),
        on_delete=models.SET_NULL,
        related_name="%(app_label)s_%(class)s_updated_by",
        to=settings.AUTH_USER_MODEL,
        blank=True,
        null=True,
        help_text=_("User who updated the object"),
    )

    class Meta:
        abstract = True
